def _situation_terminal_effects(kind: str, severity: int, polarity: str):
    """situation 终结一锤子永久效果。按 severity 推量级（轻 50 / 中 65 / 重 80）。
    resolve：达成（bar→100）落永久回血/加成，所有 situation 都有。
    fail：仅「会崩坏」局势（_COLLAPSIBLE_KINDS）有，崩坏（bar→0）落永久重创，幅度重于回血。
    民心/皇威由 kind 倾向决定（边事/外族偏皇威，灾害/民变偏民心，余者两者兼得）。"""
    mag = 1 if severity < 55 else (2 if severity < 70 else 3)
    if kind in ("外族", "边事", "友邦", "归附", "盟约", "战机", "敌乱"):
        axis = "皇威"
    elif kind in ("天灾", "灾情", "饥荒", "人祸", "兵变", "流寇", "民变", "抗税", "丰收", "祥瑞", "民和"):
        axis = "民心"
    else:
        axis = "both"

    def _metrics(amount: int) -> Dict[str, int]:
        if axis == "both":
            half = max(1, abs(amount) // 2)
            s = 1 if amount > 0 else -1
            return {"民心": s * half, "皇威": s * half}
        return {axis: amount}

    resolve_amt = (3 if polarity == "neg" else 4) * mag
    effect_resolve = {"metrics": _metrics(resolve_amt)}
    effect_fail = {"metrics": _metrics(-5 * mag)} if kind in _COLLAPSIBLE_KINDS else {}
    return effect_resolve, effect_fail

def settle_exposure_from_canonical_actions(db: Any, state: Any, applied: Mapping[str, object]) -> int:
    """只凭 canonical applier 已成功落库的结果消费待办。"""
    consumed = 0
    for todo in db.list_next_audience_todos(status="pending"):
        if todo.get("entry_kind") != ENTRY_KIND:
            continue
        payload = todo.get("payload_json") or {}
        did = int(payload.get("dossier_id") or 0)
        # The same row remains the durable reminder only while the real gap exists.
        if payload.get("decision") == "禁摊派":
            pay_fact = army_pay_fact_for_dossier(db, did) or {}
            if float(pay_fact.get("arrears") or 0) <= 0:
                db.mark_next_audience_todo_status(int(todo["id"]), "consumed", commit=False)
                consumed += 1
            continue
        if payload.get("decision"):
            continue
        origin = f"dossier:{did}"
        dossier = db.get_decree_dossier(did) or {}
        actors = {str(dossier.get("executor_id") or "").strip()}
        for participant in dossier.get("participant_roster") or []:
            if isinstance(participant, Mapping) and participant.get("tier") in {"主办", "协办"}:
                actors.add(str(participant.get("character_id") or "").strip())
        actors.discard("")
        successful = lambda x: isinstance(x, Mapping) and not x.get("rejected")
        # Identity is the successfully promulgated case-bound dossier, never an
        # unrelated fiscal receipt with a convenient shape.
        pay_fact = army_pay_fact_for_dossier(db, did) or {}
        prohibition = active_prohibition_dossier(db, did)
        stopped = prohibition is not None
        if prohibition is not None:
            # The canonical prohibition owns the durable, idempotent rollback receipt.
            from ming_sim.issues import neutralize_covert_fiscal_effects
            neutralize_covert_fiscal_effects(
                db, state, exposed_dossier_id=did,
                prohibition_dossier_id=int(prohibition["id"]),
            )
        levy_transfer = any(
            is_actual_population_transfer(x)
            and x.get("origin_ref") == origin and x.get("reason") == "摊派"
            for x in applied.get("population_transfers") or []
        )
        covert_effect = any(
            successful(x) and x.get("applied") is True
            and x.get("origin_ref") == origin and x.get("beyond_intent") is True
            for key in ("economy_moves", "fiscal_changes", "fiscal_creates", "fiscal_removes")
            for x in applied.get(key) or []
        )
        person_changes = list(applied.get("applied_person_changes") or [])
        person_changes += list((applied.get("issue_summary") or {}).get("applied_person_changes") or [])
        punished = any(
            successful(x) and x.get("动作") in {"处置", "罢黜"}
            and str(x.get("name") or "") in actors for x in person_changes
        )
        paid_cost = any(
            successful(x)
            and str(x.get("origin") or "").startswith(f"{origin}:relation:")
            and ({str(x.get("source") or ""), str(x.get("target") or "")} & actors)
            for x in applied.get("relation_edge_event_resolutions") or []
        )
        decisions = [
            name for name, matched in (
                ("禁摊派", stopped), ("默许", levy_transfer and covert_effect),
                ("查办", punished and paid_cost),
            ) if matched
        ]
        if len(decisions) != 1:
            continue
        decision = decisions[0]
        # 禁令的真实后果是欠饷缺口继续顶在御前，故保留同一 pending 行而非造第二 dispatcher。
        reopened = (
            decision == "禁摊派" and float(pay_fact.get("arrears") or 0) > 0
        )
        status = "pending" if reopened else "consumed"
        db.mark_next_audience_todo_status(
            int(todo["id"]), status,
            payload_patch={"decision": decision, "decided_turn": int(state.turn),
                           "shortfall_reopened": reopened}, commit=False,
        )
        consumed += 1
    return consumed

def validate_affected_parties(
    affected: object, *, faction_names: object, class_names: object,
) -> None:
    """Validate typed signed reactions; extra explanatory keys remain allowed."""
    if not isinstance(affected, list) or not all(
        isinstance(item, dict)
        and {"kind", "key", "direction", "intensity"}.issubset(item)
        and item.get("kind") in {"faction", "class"}
        and isinstance(item.get("key"), str)
        and item["key"] in (faction_names if item.get("kind") == "faction" else class_names)
        and item.get("direction") in {"positive", "negative"}
        and item.get("intensity") in {"weak", "strong"}
        for item in affected
    ):
        raise ValueError("affected_parties 须为在册 typed signed 反应清单")

def persist_answers(db: Any, state: Any, choices: list, *, content: Any = None) -> None:
    """Validate the entire envelope before writing. Same-body retries are idempotent."""
    requests = [canonical_choice(raw) for raw in choices]
    keys = [item["decision_key"] for item in requests]
    if len(set(keys)) != len(keys):
        raise ValueError("重复 decision_key")
    rows = {r["decision_key"]: r for r in db.get_rescript_desk_rows_by_keys(keys)}
    open_keys = {r["decision_key"] for r in db.list_rescript_desk(int(state.turn))}
    for choice in requests:
        row = rows.get(choice["decision_key"])
        if row is None:
            raise ValueError("decision_key 不在案头")
        if row["choice"]:
            if row["choice"] != choice:
                raise ValueError("已落批语不可改写")
            continue
        if choice["decision_key"] not in open_keys:
            raise ValueError("原案当前不可批")
        event_id = str(row.get("event_id") or "")
        action = choice.get("dossier_decision") or choice.get("action") or ""
        if event_id.startswith("dossier:"):
            legal = {o.get("dossier_decision") for o in row["options"]}
            if action not in legal:
                raise ValueError("打回旨须显式选择合法强颁、收回或留中")
        elif event_id.startswith("deliberation:"):
            if action not in {o.get("action") for o in row["options"]}:
                raise ValueError("无人站台案须显式选择御笔强推或留存")
        else:
            if action not in ({"", "midzhi"} if row["kind"] == "rescript_draft" else {""}):
                raise ValueError("批语不使用旧六动作；另旨·中旨只接急务原案")
            if not (choice.get("label", "").strip() or choice.get("note", "").strip()):
                raise ValueError("批语为空")
            if choice.get("label") and choice["label"] not in {o.get("label") for o in row["options"]}:
                raise ValueError("所选票拟不在原奏折中")
    with atomic_and_reload(db, state, content=content):
        order = int(db.conn.execute(
            "SELECT COALESCE(MAX(answer_order),0) FROM pending_decisions WHERE answered_turn=?", (int(state.turn),),
        ).fetchone()[0])
        for choice in requests:
            row = rows[choice["decision_key"]]
            if row["choice"]:
                continue
            order += 1
            db.conn.execute(
                "UPDATE pending_decisions SET choice_json=?, status='decided', answered_turn=?, answer_order=? "
                "WHERE turn=? AND idx=? AND kind=? AND status='pending'",
                (json.dumps(choice, ensure_ascii=False), int(state.turn), order,
                 row["source_turn"], row["idx"], row["kind"]),
            )
            event_id = str(row.get("event_id") or "")
            from ming_sim.month_chain import _DECREE_QUESTION_PREFIX, _WORLD_QUESTION_PREFIX
            if row["kind"] == "decision" and event_id and not event_id.startswith(
                ("dossier:", "deliberation:", _DECREE_QUESTION_PREFIX, _WORLD_QUESTION_PREFIX)
            ):
                db.record_event_decision_choice(state, event_id, choice, commit=False)

def list_unsettled_summons(db: Any) -> List[Dict[str, Any]]:
    """从故事账确定性投影未结传召；不解析自由叙事正文。"""
    rows = db.conn.execute(
        "SELECT id, night_id, person_names, tags FROM story_ledger_entries ORDER BY id"
    ).fetchall()
    projected: List[Dict[str, Any]] = []
    for row in rows:
        tags = json.loads(row["tags"] or "[]")
        if TAG_SUMMON_UNSETTLED not in tags or TAG_SUMMON_SETTLED in tags:
            continue
        origin = next(
            (str(tag)[len(_SUMMON_ORIGIN_PREFIX):] for tag in tags
             if str(tag).startswith(_SUMMON_ORIGIN_PREFIX)),
            "",
        )
        names = json.loads(row["person_names"] or "[]")
        if not origin or not names:
            continue
        person_name = str(names[0])
        projected.append({
            "entry_id": int(row["id"]), "night_id": int(row["night_id"]),
            "person_name": person_name, "origin_id": origin,
            "kind": _project_unsettled_summon_kind(db, tags, person_name),
            **({"travel_tone": _travel_tone_from_tags(tags)}
               if any(str(tag).startswith(_SUMMON_TRAVEL_TONE_PREFIX) for tag in tags)
               else {}),
        })
    return projected

def _secret_metadata_from_command(text: str) -> Tuple[List[str], int]:
    tags: List[str] = []
    deadline = 0
    for raw_line in (text or "").splitlines():
        line = raw_line.strip()
        if not line:
            continue
        m_tags = re.match(r"^(?:标签|tag|tags)\s*[：:]\s*(.+)$", line, flags=re.IGNORECASE)
        if m_tags:
            for item in re.split(r"[,，、/;；\s]+", m_tags.group(1)):
                cleaned = item.strip()
                if cleaned and cleaned not in tags:
                    tags.append(cleaned)
            continue
        m_deadline = re.match(r"^(?:期限|限期|deadline)\s*[：:]\s*(.+)$", line, flags=re.IGNORECASE)
        if m_deadline:
            match = re.search(r"([+-]?\d+)\s*(?:个)?月", m_deadline.group(1))
            if match:
                deadline = max(0, min(int(match.group(1)), 36))
    return tags, deadline

def _validate_dossier_endorsement(
    self, dossier_id: object, *, form: object,
    source_chat_turn_id: object = 0, decision_key: object = "",
    endorser_id: object = "", imperial: object = False,
) -> tuple[int, int, str, str, str, bool]:
    """#658：provenance 恰取 source_chat_turn_id>0 或 decision_key 非空之一。"""
    if isinstance(dossier_id, bool) or not isinstance(dossier_id, int):
        raise ValueError("背书案卷 id 须为整数")
    if isinstance(source_chat_turn_id, bool) or not isinstance(source_chat_turn_id, int):
        raise ValueError("背书来源对话轮 id 须为整数")
    if not isinstance(decision_key, str):
        raise ValueError("背书 decision_key 须为字符串")
    if not isinstance(form, str) or not isinstance(endorser_id, str):
        raise ValueError("背书形式与人物须为字符串")
    did, cid = dossier_id, int(source_chat_turn_id)
    dkey = decision_key.strip()
    kind, person = form.strip(), endorser_id.strip()
    if not isinstance(imperial, bool):
        raise ValueError("御笔标记须为布尔")
    is_imperial = imperial
    # 恰一种 provenance：召对 chat_turn XOR 批红/下旨 decision_key。
    has_turn = cid > 0
    has_key = bool(dkey)
    if has_turn == has_key:
        raise ValueError("背书 provenance 须恰为 source_chat_turn_id 或 decision_key 之一")
    if self.conn.execute("SELECT 1 FROM decree_dossiers WHERE id=?", (did,)).fetchone() is None:
        raise ValueError("背书所指案卷不存在")
    if has_turn:
        if self.conn.execute("SELECT 1 FROM chat_turns WHERE id=?", (cid,)).fetchone() is None:
            raise ValueError("背书来源对话轮不存在")
    if kind not in {"会签", "当面站台", "御笔手敕"}:
        raise ValueError("背书形式非法")
    if kind == "御笔手敕":
        if not is_imperial or person:
            raise ValueError("御笔手敕必须使用御笔标记且不得具名大臣")
    else:
        if is_imperial or not person:
            raise ValueError("会签/当面站台必须具名背书人")
        if self.conn.execute("SELECT 1 FROM characters WHERE name=?", (person,)).fetchone() is None:
            raise ValueError("背书人物不存在")
    return did, cid, dkey, kind, person, is_imperial

def _apply_ordinary_entity_step(
    step_extracted: Dict[str, object],
    step_ordered: Dict[str, list[tuple[str, object]]],
    step_event_ids: dict[str, list[str]],
) -> None:
    step_new_armies = step_extracted.get("new_armies") or []
    declared = step_event_ids.get("new_armies") or []
    for idx, army_item in enumerate(step_new_armies):
        if not isinstance(army_item, dict):
            continue
        event_for_item = declared[idx] if idx < len(declared) else ""
        if event_for_item in strategic_event_referenced_ids:
            continue
        origin_ref = str(army_item.get("origin_ref") or "").strip()
        created_armies.extend(db.create_armies_from_extraction(
            state, [army_item], actor="档房", commit=commit_now,
            origin_ref=origin_ref, require_origin=True,
        ))
    for index, (region_id, raw_changes) in enumerate(step_ordered.get("region_delta") or []):
        if _effect_event_ids(
            "region_delta", index, strategic_event_referenced_ids, step_event_ids,
        ):
            continue
        origin_ref = str(raw_changes.get("origin_ref") or "").strip()
        payload = {k: v for k, v in raw_changes.items() if k != "origin_ref"}
        region_changes.extend(db.apply_region_deltas(
            state, pseudo_event, None, "档房", {region_id: payload},
            commit=commit_now, origin_ref=origin_ref, require_origin=True,
        ))
    for index, (army_id, raw_changes) in enumerate(step_ordered.get("army_delta") or []):
        if _effect_event_ids(
            "army_delta", index, strategic_event_referenced_ids, step_event_ids,
        ):
            continue
        army_changes.extend(_apply_extracted_army_delta(
            db, state, pseudo_event, army_id, raw_changes, commit_now=commit_now,
        ))

def _resolve_inside(root: Path, rel: str) -> Path:
    root_r = root.resolve()
    raw = str(rel or "").strip()
    if not raw or raw in {".", "./"}:
        return root_r
    if Path(raw).is_absolute() or raw.startswith("~"):
        raise ValueError("材料路径越出目录")
    candidate = (root_r / raw).resolve()
    try:
        candidate.relative_to(root_r)
    except ValueError as exc:
        raise ValueError("材料路径越出目录") from exc
    return candidate

def _match_rank_rule(
    title: str, table: dict[str, Any], required_field: str
) -> Optional[dict[str, Any]]:
    """Return the longest matching stem that defines the requested behavior."""
    text = str(title or "").strip()
    if not text:
        return None
    best: Optional[dict[str, Any]] = None
    best_score = (-1, -1)
    for rule in _iter_rank_rules(table):
        if required_field not in rule:
            continue
        # Leverage-bearing rules describe substantive titles.  Rank-only rules also
        # contain institutional/category fallbacks such as 翰林院 and 锦衣卫.
        title_specific = int(
            required_field == "rank_band" and "leverage_multiplier" in rule
        )
        for stem in rule.get("stems") or []:
            token = str(stem or "").strip()
            if not token or token not in text:
                continue
            score = (title_specific, len(token))
            if score > best_score:
                best = rule
                best_score = score
    return best

def season_option_contract_prompt(kind: str) -> str:
    """Human-facing season option contract projected from FieldSpec."""
    specs = _season_specs(kind)
    details = []
    effective_values: Dict[str, FrozenSet[str]] = {}
    for spec in specs:
        detail = spec.name
        if spec.allowed is not None:
            allowed = frozenset(
                value for value in spec.allowed
                if all(
                    field_population_allowed(kind, dependent.name, {spec.name: value})
                    for dependent in specs
                    if dependent.populated_when is not None
                    and dependent.populated_when[0] == spec.name
                )
            )
            effective_values[spec.name] = allowed
            if spec.allowed_when is not None:
                controller = spec.allowed_when[0]
                controller_values = effective_values.get(controller, frozenset())
                context = (
                    {controller: next(iter(controller_values))}
                    if len(controller_values) == 1 else {}
                )
                allowed = effective_field_allowed(spec, context) or frozenset()
            detail += f'（{"|".join(sorted(allowed))}）'
        if spec.as_int:
            detail += f"（JSON integer，{spec.int_lo}..{spec.int_hi}，禁数字字符串）"
        if spec.quantity_unit:
            detail += f"（单位={spec.quantity_unit}）"
        details.append(detail)
    if not details:
        return ""
    return (
        f'协饷 option 须携带 action_type="{kind}"、'
        + "、".join(details)
        + "；非协饷 option 保持既有 label/hint，不携带这些字段。"
    )

def project_applicable_authorities(
    self, turn: int, dossier: Mapping[str, object],
) -> List[Dict[str, object]]:
    """#611 unique applicability projection over durable authority rows.

    Actors = character executor ∪ roster 主办/协办 (never payload assignee).
    Domains = only the typed canonical key target_kind:target_id.
    """
    actors: set[str] = set()
    executor_id = str(dossier.get("executor_id") or "").strip()
    executor_kind = str(dossier.get("executor_kind") or "").strip()
    if executor_id and executor_kind in {"", "character"}:
        actors.add(executor_id)
    roster = dossier.get("participant_roster") or []
    if isinstance(roster, str):
        try:
            roster = json.loads(roster)
        except (TypeError, ValueError):
            roster = []
    if isinstance(roster, list):
        for entry in roster:
            if not isinstance(entry, dict):
                continue
            if str(entry.get("tier") or "").strip() not in {"主办", "协办"}:
                continue
            character_id = str(entry.get("character_id") or "").strip()
            if character_id:
                actors.add(character_id)
    target_kind = str(dossier.get("target_kind") or "").strip()
    target_id = str(dossier.get("target_id") or "").strip()
    domains: set[str] = set()
    if target_kind and target_id:
        domains.add(f"{target_kind}:{target_id}")
    if not actors or not domains:
        return []
    projected: List[Dict[str, object]] = []
    for holder_id in sorted(actors):
        for row in self.list_active_authorities(int(turn), holder_id=holder_id):
            if str(row.get("scope") or "") not in domains:
                continue
            projected.append({
                "id": int(row["id"]),
                "holder_id": str(row["holder_id"]),
                "privilege": str(row["privilege"]),
                "scope": str(row["scope"]),
                "effective_turn": int(row["effective_turn"]),
                **(
                    {"expires_turn": int(row["expires_turn"])}
                    if row.get("expires_turn") is not None else {}
                ),
            })
    projected.sort(key=lambda item: int(item["id"]))
    return projected

def _event_chain_impossible_reason(ev: Event, terminal_records: Dict[str, Dict[str, str]], state: GameState) -> str:
    allowed_states: Dict[str, set[str]] = {}
    forbidden_states: Dict[str, set[str]] = {}
    allowed_outcomes: Dict[str, set[str]] = {}
    forbidden_outcomes: Dict[str, set[str]] = {}

    def _format_values(values: set[str]) -> str:
        return "|".join(sorted(values))

    def allow_states(upstream_id: str, state_names: set[str], *, raw_key: object, raw_cond: str) -> None:
        if not state_names:
            return
        existing = allowed_states.get(upstream_id)
        if existing is None:
            allowed_states[upstream_id] = set(state_names)
            return
        narrowed = existing & state_names
        if not narrowed:
            raise SettlementAbort(
                "事件链正向终态门互相矛盾："
                f"{upstream_id} 已要求 {{{_format_values(existing)}}}，"
                f"又要求 {{{_format_values(state_names)}}}（{raw_key} {raw_cond}）",
                turn=state.turn,
                stage="event_chain_config",
            )
        allowed_states[upstream_id] = narrowed

    def allow_state(upstream_id: str, state_name: str, *, raw_key: object, raw_cond: str) -> None:
        allow_states(upstream_id, {state_name}, raw_key=raw_key, raw_cond=raw_cond)

    def allow_outcomes(upstream_id: str, outcomes: set[str], *, raw_key: object, raw_cond: str) -> None:
        if not outcomes:
            return
        existing = allowed_outcomes.get(upstream_id)
        if existing is None:
            allowed_outcomes[upstream_id] = set(outcomes)
            return
        narrowed = existing & outcomes
        if not narrowed:
            raise SettlementAbort(
                "事件链正向结局门互相矛盾："
                f"{upstream_id} 已要求 {{{_format_values(existing)}}}，"
                f"又要求 {{{_format_values(outcomes)}}}（{raw_key} {raw_cond}）",
                turn=state.turn,
                stage="event_chain_config",
            )
        allowed_outcomes[upstream_id] = narrowed

    def forbid_state(upstream_id: str, state_name: str) -> None:
        forbidden_states.setdefault(upstream_id, set()).add(state_name)

    for raw_key, raw_cond in (ev.trigger_gate or {}).items():
