def review_directives(session: GameSession) -> str:
    """诏书草案审阅界面。返回 'issue' | 'back' | 'skip'。"""
    session.enter_review()
    while True:
        directives = session.list_directives(include_pending=True)
        pending = [d for d in directives if d.status == "pending"]
        drafts = [d for d in directives if d.status == "draft"]
        staged_directives = [
            p for p in session.db.list_pending_actions(session.state.turn)
            if p.get("kind") == "directive"
        ]
        print(f"\n本{TURN_UNIT}诏书草案：")
        if pending:
            print(f"  · {len(pending)} 道历史拟旨候结束回合成案：")
            for d in pending:
                print(f"  [待核定] #{d.id}  {wrap(d.text)}")
        if staged_directives:
            print(f"  · {len(staged_directives)} 道对话拟旨待颁诏默认同意。")
        if drafts:
            for idx, d in enumerate(drafts, 1):
                print(f"{idx}. #{d.id}")
                print(f"   {wrap(d.text)}")
        elif not pending and not staged_directives:
            print("（暂无指令。back 继续召见，或 add 新增。）")
        print("\n操作：issue 结束回合 | back 继续召见 | add 新增 | edit N 改 | del N 删 | exit 退出")
        raw = input("诏书草案> ").strip()
        if not raw:
            continue
        lowered = raw.lower()
        if lowered in EXIT_COMMANDS:
            raise ExitGame
        if lowered in COURT_BREAK_COMMANDS:
            if drafts or pending or staged_directives:
                print(f"本{TURN_UNIT}尚有候选旨意；退朝将按结束回合规则成案。请输入 issue。")
                continue
            return "skip"
        if lowered in {"back", "b", "返回", "继续召见"}:
            from ming_sim.session import FRONT_HALF_DONE_PHASES
            if session.state.turn_phase in FRONT_HALF_DONE_PHASES:
                # 粘滞相位下 back 是静默 no-op，play_turn 会立刻把人弹回本菜单——
                # 给一行提示，别让玩家以为按键失灵（ship-pre r6）。
                print("\n上月结算未完成，无法继续召见；请输入 issue 续跑结算。")
                continue
            session.back_to_summoning()
            return "back"
        if lowered in {"issue", "颁布", "颁布诏书", "发布", "拟诏"}:
            from ming_sim.session import FRONT_HALF_DONE_PHASES
            if session.state.turn_phase in FRONT_HALF_DONE_PHASES:
                # 恢复态：上月结算未完成（崩溃/中止后），跳过拟诏直接续跑结算——
                # resolve_turn 的恢复分流自己决定重放/重新推演/回放决策点
                # （ship-pre r3：write_decree 在此态必拒，不开此口 CLI 永远够不到恢复入口）。
                print("\n检测到上月结算未完成，续跑结算……")
                return "issue"
            return "issue"
        # 变更器统一接 ValueError（FRONT_HALF_DONE 冻结期的指引消息）：打印后留在
        # 审阅循环，不崩出进程（ship-pre r2，与 write_decree 既有 try 同款）。
        try:
            if lowered == "add" or raw == "新增":
                text = input("指令内容：")
                if text.strip():
                    from ming_sim.cli_backend import capture_manual_directive_payload
                    dv = session.add_directive(
                        text,
                        dossier_payload=capture_manual_directive_payload(
                            text, session.llm_config,
                            **({"db": session.db, "content": session.content}
                               if getattr(session, "content", None) is not None else {}),
                        ),
                    )
                    print(f"已新增草案 #{dv.id}。")
                else:
                    print("指令为空，已取消。")
                continue
            parts = raw.split(maxsplit=1)
            verb = parts[0].lower()
            if len(parts) == 2 and parts[1].lstrip("#").isdigit():
                target_id = int(parts[1].lstrip("#"))
                if verb in {"edit", "改", "修改"}:
                    if not any(d.id == target_id for d in drafts):
                        print("没有这条草案。")
                        continue

def match_minister_from_text(text: str, current: Optional[Character] = None) -> Optional[Character]:
    cleaned = text.strip()
    if not cleaned:
        return None
    matches = []
    for character in _ctx().characters.values():
        if current is not None and character.name == current.name:
            continue
        if (
            character.name in cleaned
            or character.office in cleaned
            or character.office_type in cleaned
            or character.faction in cleaned
            or any(alias in cleaned for alias in character.aliases)
        ):
            matches.append(character)
    if len(matches) == 1:
        return matches[0]
    if len(matches) > 1:
        exact = [character for character in matches if character.name in cleaned]
        if len(exact) == 1:
            return exact[0]
    return None

def _office_type_from_table(text: str) -> str:
    """按 offices.json priority 顺序，首个命中词干者胜。无命中返回 ''。"""
    for entry in _offices_table().get("priority", []) or []:
        if not isinstance(entry, dict):
            continue
        for stem in entry.get("stems", []) or []:
            if stem and stem in text:
                return str(entry.get("type") or "")
    return ""

def origin_ref_from_result_item(
    self,
    item: Mapping[str, object] | None,
    *,
    year: int,
    period: int,
    turn: int,
    authorized_ids: set[int] | None = None,
) -> str:
    """Birth declaration on a result item becomes affair:<id> when origin_ref is empty."""
    if not item:
        return ""
    origin_ref = str(item.get("origin_ref") or item.get("来源引用") or "").strip()
    if origin_ref:
        kind, target = parse_origin_ref(origin_ref)
        if (
            kind == _ORIGIN_AFFAIR
            and authorized_ids is not None
            and target not in authorized_ids
        ):
            raise UnauthorizedAffairOriginRef()
        return origin_ref
    parsed = declaration_from_payload(item, allowed=ATTACH_BIRTH)
    if parsed is None:
        return ""
    if parsed["attach"] == _ATTACH_EXISTING and authorized_ids is not None:
        if int(parsed["affair_id"]) not in authorized_ids:
            raise UnauthorizedAffairOriginRef()
    affair_id = self.resolve_declaration(
        parsed, year=year, period=period, turn=turn, allowed=ATTACH_BIRTH,
    )
    # Same-batch births become authorized for later durable-effect carriers.
    if authorized_ids is not None:
        authorized_ids.add(int(affair_id))
    return self.origin_ref(affair_id)

