def _loads_lenient(
    raw: str, *, accepted_types: tuple[type, ...] = (dict,),
) -> Optional[Any]:
    """容错解析 JSON：剥代码围栏并截取首个受理容器。失败返回 None。"""
    t = (raw or "").strip()
    if t.startswith("```"):
        t = re.sub(r"^```[a-zA-Z]*\s*", "", t)
        t = re.sub(r"\s*```$", "", t).strip()
    starts = []
    if dict in accepted_types:
        starts.append((t.find("{"), "}"))
    if list in accepted_types:
        starts.append((t.find("["), "]"))
    starts = [(index, closer) for index, closer in starts if index >= 0]
    if not starts:
        return None
    i, closer = min(starts, key=lambda item: item[0])
    j = t.rfind(closer)
    if j <= i:
        return None
    body = t[i:j + 1]
    try:
        obj = json.loads(body)
    except (ValueError, TypeError):
        # 严格解析失败才做 JSONC 容错（CMR F8）：模型照 prompt 模板回带 // 行注释或尾逗号时救回。
        # 先严格、失败才清洗 —— 合法 JSON 不经清洗器。清洗器 quote-aware：串值里的 //、,}、://
        # 一律不动（#6，旧裸正则会误伤 "x,}"→"x}"、"a//b"→截断）。
        try:
            obj = json.loads(_strip_jsonc(body))
        except (ValueError, TypeError):
            return None
    return obj if isinstance(obj, accepted_types) else None

def coerce_covert_task_contract(raw: object) -> Optional[Dict[str, object]]:
    """Validate a frozen contract without rebuilding or supplying read-time defaults."""
    if not isinstance(raw, Mapping) or raw.get("version") != CONTRACT_VERSION:
        return None
    delivery = raw.get("delivery")
    if not isinstance(delivery, Mapping):
        return None
    if not str(raw.get("kind") or "").strip() or not normalize_axes(raw.get("axes")):
        return None
    if raw.get("direction") not in (-1, 1):
        return None
    inv_target = str(
        raw.get("investigation_target") or delivery.get("investigation_target") or ""
    ).strip()
    if inv_target:
        try:
            qty = float(delivery.get("target_units"))
        except (TypeError, ValueError):
            return None
        if qty <= 0.0:
            return None
        if delivery.get("effect_sign") not in (-1, 1):
            return None
        if list(delivery.get("canonical_fields") or []):
            return None
        if str(delivery.get("investigation_target") or "").strip() != inv_target:
            return None
        return copy.deepcopy(dict(raw))
    try:
        unit, target = canonicalize_delivery_unit(
            delivery.get("unit"), delivery.get("target_units"),
        )
    except CovertContractError:
        return None
    if delivery.get("effect_sign") not in (-1, 1):
        return None
    if list(delivery.get("canonical_fields") or []) != canonical_fields_for_delivery(unit=unit):
        return None
    if float(delivery.get("target_units")) != target:
        return None
    if any(
        not delivery.get(key)
        for key in _identity_keys_for_unit(
            str(unit),
            effect_sign=int(delivery.get("effect_sign") or 0),
            purpose=delivery.get("purpose"),
        )
    ):
        return None
    return copy.deepcopy(dict(raw))

def list_decree_dossiers(
    self, *, status: Optional[str] = None, target_kind: Optional[str] = None,
    target_id: Optional[object] = None,
) -> List[Dict[str, object]]:
    clauses: List[str] = []
    params: List[object] = []
    if status is not None:
        if status not in self._DOSSIER_STATUSES:
            raise ValueError(f"案卷 status 非法：{status}")
        clauses.append("status=?")
        params.append(status)
    if target_kind is not None:
        clauses.append("target_kind=?")
        params.append(str(target_kind))
    if target_id is not None:
        clauses.append("target_id=?")
        params.append(str(target_id))
    where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
    rows = self.conn.execute(
        f"SELECT * FROM decree_dossiers{where} ORDER BY id", params
    ).fetchall()
    return [self._dossier_row(row) for row in rows]

def record_dossier_progress(
    self,
    dossier_id: int,
    turn: int,
    progress_band: str,
    memorial_text: str,
    *,
    is_terminal: bool = False,
    origin: str = "",
    commit: bool = True,
) -> int:
    """Append one reported-progress entry; write path splits by physical track.

    Secret-order dossiers stay on secret_orders.dossier_progress_json (#566).
    Non-secret execution-surface dossiers use dossier_reported_progress (#619).
    Reported rows never enter apply (ADR 0073).
    """
    dossier = self.get_decree_dossier(int(dossier_id))
    band = str(progress_band or "").strip()
    text = str(memorial_text or "")
    if dossier is None:
        raise ValueError("案卷不存在")
    if not band or not text.strip():
        raise ValueError("进展档和密奏均不能为空")
    origin_norm = self._normalize_dossier_report_origin(
        origin, is_terminal=bool(is_terminal),
    )
    secret_order_id = dossier.get("secret_order_id")
    if secret_order_id:
        return self._record_secret_dossier_progress(
            int(dossier_id), int(secret_order_id), int(turn), band, text,
            is_terminal=bool(is_terminal), origin=origin_norm, commit=commit,
        )
    payload = {}
    try:
        loaded = json.loads(str(dossier.get("payload_json") or "{}"))
        if isinstance(loaded, dict):
            payload = loaded
    except (TypeError, ValueError):
        payload = {}
    if not self._dossier_has_execution_surface(dossier.get("action_type"), payload):
        raise ValueError("非执行面案卷不可挂奏报")
    return self._record_general_dossier_progress(
        int(dossier_id), int(turn), band, text,
        is_terminal=bool(is_terminal), origin=origin_norm, commit=commit,
    )

def _assert_commission_grant_target_exists(
    db: Any, target_kind: str, target_id: str,
) -> None:
    """拨帑目标必须是账上真实体；查无 → KeyError（hallucinated_id）。"""
    kind = str(target_kind or "").strip()
    tid = str(target_id or "").strip()
    if kind == "region":
        row = db.conn.execute("SELECT 1 FROM regions WHERE id=?", (tid,)).fetchone()
        if row is None:
            raise KeyError(f"地区不存在：{tid}")
        return
    if kind == "character":
        _assert_characters_exist(db, [tid])
        return
    if kind == "army":
        row = db.conn.execute("SELECT 1 FROM armies WHERE id=?", (tid,)).fetchone()
        if row is None:
            raise KeyError(f"军队不存在：{tid}")
        return
    if kind == "issue":
        try:
            iid = int(tid)
        except (TypeError, ValueError) as exc:
            raise KeyError(f"事项不存在：{tid}") from exc
        row = db.conn.execute("SELECT 1 FROM issues WHERE id=?", (iid,)).fetchone()
        if row is None:
            raise KeyError(f"事项不存在：{tid}")
        return

def render_referenceable_dossier_brief(candidates) -> str:
    """认账唯一 brief 渲染：status/颁布格/执行格/中旨标记一律定性中文。"""
    if not candidates:
        return ""
    lines = [
        "【可参考既有旨意（若有关联，请按标题或事项复述；勿向陛下念内部编号）】",
    ]
    for row in candidates:
        if not isinstance(row, dict):
            continue
        title = str(
            row.get("secret_title") or row.get("decree_text") or row.get("action_type") or ""
        )
        status_cn = qualitative_dossier_status(row.get("status"))
        decision_cn = qualitative_promulgation_slot(row)
        outcome_cn = qualitative_dossier_outcome(
            row.get("execution_outcome"), status=row.get("status"),
        )
        note = str(row.get("execution_note") or "")
        markers = qualitative_midzhi_markers(row)
        facts = []
        if status_cn:
            facts.append(f"状态：{status_cn}")
        if decision_cn:
            facts.append(f"颁布：{decision_cn}")
        if outcome_cn:
            facts.append(f"执行：{outcome_cn}")
        if note:
            facts.append(f"说明：{note}")
        if markers:
            facts.append("标记：" + "、".join(markers))
        fact_text = "；".join(facts)
        suffix = f"（{fact_text}）" if fact_text else ""
        lines.append(f"- [内部键 {int(row['id'])}] {title}{suffix}")
    return "\n".join(lines)

def _admit_transit_departure(
    item: Dict[str, object],
    row: Dict[str, object],
    valid_regions: set[str],
) -> tuple[Optional[Dict[str, object]], Optional[tuple[str, str]]]:
    """Return the canonical, write-free departure projection or its item rejection."""
    if "location" in item:
        return None, ("行止只接受 transit_to 启程", "invalid_transition")
    transit_to = str(item.get("transit_to") or "").strip()
    if not transit_to:
        return None, ("transit_to 缺失", "missing_field")
    if str(row.get("status") or "active") != "active":
        return None, ("行止 仅适用于 active 人物", "invalid_transition")
    if transit_to not in valid_regions:
        return None, ("transit_to 地区不存在", "missing_ref")
    try:
        tone = normalize_travel_tone(item.get("行程语气"))
    except ValueError:
        return None, ("行程语气不在闭合枚举", "invalid_enum")
    previous_destination = str(row.get("transit_to") or "")
    if previous_destination and previous_destination != transit_to:
        return None, ("在途人物不可改道", "invalid_transition")
    location = str(row.get("location") or "")
    if location not in valid_regions:
        return None, None
    matrix = DistanceMatrix.from_file(bundled_path("content", "distance_matrix.json"))
    distance = matrix.travel_time(location, transit_to)
    if not math.isfinite(distance) or distance < 0 or (location != transit_to and distance <= 0):
        raise ValueError(f"invalid baked travel time: {location!r} -> {transit_to!r}")
    terminal_location = transit_to if distance == 0 else location
    terminal_transit_to = "" if distance == 0 else transit_to
    return {
        "location": terminal_location,
        "transit_to": terminal_transit_to,
        "distance": distance,
        "tone": tone,
        "speed": None if distance == 0 else TRAVEL_SPEED_BY_TONE[tone],
        "material": (
            terminal_location != location
            or terminal_transit_to != previous_destination
        ),
    }, None

def _monthly_person_rating_changes(effect: Dict[str, object]) -> List[Dict[str, object]]:
    raw_changes: List[Dict[str, object]] = []
    for key in ("人物变更", "person_changes"):
        raw = effect.get(key)
        if isinstance(raw, list):
            raw_changes.extend(item for item in raw if isinstance(item, dict))
    changes = [
        item
        for item in normalize_person_changes({"人物变更": raw_changes})
        if isinstance(item, dict)
        and str(item.get("动作") or "").strip() == "评定"
        and not isinstance(item.get("loyalty"), bool)
        and isinstance(item.get("loyalty"), int)
        and int(item.get("loyalty") or 0) != 0
    ]
    raw_character = effect.get("character")
    if isinstance(raw_character, list):
        for item in raw_character:
            if not isinstance(item, dict):
                continue
            name = str(item.get("name") or item.get("人物") or "").strip()
            loyalty = item.get("loyalty")
            if not name or isinstance(loyalty, bool) or not isinstance(loyalty, int) or loyalty == 0:
                continue
            changes.append({
                "name": name,
                "动作": "评定",
                "loyalty": loyalty,
                "reason": str(item.get("reason") or item.get("原因") or ""),
            })
    return changes

def _person_effect_has_work(raw: object) -> bool:
    if not isinstance(raw, list):
        return False
    for item in raw:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name") or item.get("人物") or "").strip()
        action = str(item.get("动作") or item.get("action") or "").strip()
        if not name or action not in PERSON_ACTIONS:
            continue
        if action == "评定":
            loyalty = item.get("loyalty")
            if (
                not isinstance(loyalty, bool)
                and isinstance(loyalty, int)
                and loyalty != 0
            ):
                return True
            continue
        if action == "性情":
            style = item.get("style")
            if isinstance(style, str) and style.strip():
                return True
            continue
        return True
    return False

